def load_checkpoint(prefix):
    with np.load(prefix + ".npz") as z:
        params = {k: z[k] for k in z.files} # copy out, the file closes after this block

    with open(prefix + ".json", encoding="utf-8") as f:
        cfg = ModelConfig(**json.load(f))

    with open(prefix + ".tok.json", encoding="utf-8") as f:
        d = json.load(f)

    stoi = {}
    for i in range(len(d["itos"])):
        stoi[d["itos"][i]] = i

    return params, cfg, Tokenizer(d["merges"], stoi, d["itos"])

def load_corpus(path, column, max_rows) -> str:
    df = pd.read_csv(path, nrows=max_rows)

    if column not in df.columns:
        raise ValueError(f"no column {column!r}, the file has {list(df.columns)}")

    texts = df[column].dropna().astype(str).str.strip()
    return "\n".join(texts) + "\n"

def split_ids(ids, val_fraction):
    cut = int((1 - val_fraction) * len(ids))
    return ids[:cut], ids[cut:]

def iterate_batches(inputs, targets, batch_size, rng, shuffle = True):
    order = inputs.index
    if shuffle:
        order = inputs.sample(frac=1, random_state=rng).index

    for i in range(0, len(order), batch_size):
        rows = order[i : i + batch_size]
        yield inputs.loc[rows].to_numpy(), targets.loc[rows].to_numpy()

def sample_next(logits, temperature, top_k, top_p, rng):
    if temperature < 1e-6:
        return int(np.argmax(logits))

    p = softmax_forward(logits / temperature)

    if 0 < top_k < len(p):
        cutoff = np.sort(p)[-top_k] # # k-th largest probabilit
        p = np.where(p >= cutoff, p, 0.0) # zero everything below it
        p = p / p.sum() # renormalise so it sums to 1 again

    if top_p < 1.0:
        order = np.argsort(-p)
        cum = np.cumsum(p[order])
        keep = order[: np.searchsorted(cum, top_p) + 1]
        q = np.zeros_like(p)
        q[keep] = p[keep]
        p = q / q.sum()

    return int(rng.choice(len(p), p=p))

def generate(params, cfg: ModelConfig, seed_ids, max_new_tokens, window, temperature, top_k, top_p, rng):
    ids = list(seed_ids)

    for _ in range(max_new_tokens):
        logits, _ = forward(params, np.array(ids[-window:]), cfg)
        ids.append(sample_next(logits[-1], temperature, top_k, top_p, rng)) # logits[-1] is used because the last position is the only one that has seen the whole context

    return ids

def xavier_uniform(fan_in, fan_out, rng):
    a = np.sqrt(6.0 / (fan_in + fan_out))
    return rng.uniform(-a, a, size=(fan_in, fan_out))

def softmax_forward(x):
    e = np.exp(x - np.max(x, axis=-1, keepdims=True))
    return e / e.sum(axis=-1, keepdims=True)

def cross_entropy_forward(logits, targets):
    z = logits - logits.max(axis=-1, keepdims=True)
    logp = z - np.log(np.exp(z).sum(axis=-1, keepdims=True))
    T = len(targets)
    loss = -logp[np.arange(T), targets].mean()
    return float(loss), np.exp(logp)

def layer_norm_forward(X, gamma, beta, epsilon = 1e-5):
    mu = X.mean(axis=-1, keepdims=True)
    var = ((X - mu) ** 2).mean(axis=-1, keepdims=True)
    s = 1.0 / np.sqrt(var + epsilon)
    Xhat = (X - mu) * s
    return gamma * Xhat + beta, (Xhat, s)

def lr_schedule(step, warmup, total, lr_max, lr_min):
    if step <= warmup:
        return lr_max * step / warmup # warm-up: ramp from near 0 up to lr_max, a fresh model is fragile

    frac = (step - warmup) / (total - warmup) # how far through the decay we are, goes from 0 to 1
    return lr_min + 0.5 * (lr_max - lr_min) * (1 + math.cos(math.pi * frac)) # cosine slide from lr_max down to lr_min

def clip_grad_norm(grads, max_norm):
    total = 0.0
    for k in grads:
        total += (grads[k] ** 2).sum() # add up the squares of every gradient number in every tensor
    norm = np.sqrt(total) # length of the whole gradient as one big vector

    if norm > max_norm:
        for k in grads:
            grads[k] *= max_norm / norm # shrink every tensor by the same factor, direction stays, length becomes max_norm

    return float(norm) # the length before clipping, train.py prints it as |g|

def main(prefix="checkpoints/model"):
    params, cfg, tok = load_checkpoint(prefix)
    rng = np.random.default_rng(config.seed)
    print(f"loaded {prefix}  (V={cfg.vocab_size})")
    print("Type the start of a text and press Enter. Empty line quits.")

    while True:
        try:
            prompt = input("> ")
        except EOFError:
            break

        if prompt.strip() == "":
            break

        ids = tok.encode(prompt)

        out = generate(params, cfg, ids, config.max_new_tokens, config.seq_len,
                       config.temperature, config.top_k, config.top_p, rng)

        print(tok.decode(out[len(ids):])) # only the new tokens, the prompt is already on screen

def test_save_creates_the_three_files(saved):
    prefix = saved[0]
    for ext in (".npz", ".json", ".tok.json"):
        assert open(prefix + ext, "rb").read()       # exists and is not empty

def test_config_round_trips(saved):
    prefix, _, cfg, _ = saved
    assert load_checkpoint(prefix)[1] == cfg

def test_weights_round_trip_exactly(saved):
    prefix, params, _, _ = saved
    loaded = load_checkpoint(prefix)[0]
    assert loaded.keys() == params.keys()
    for k in params:
        assert np.array_equal(loaded[k], params[k]), k

def test_tok_file_is_plain_json(saved):
    d = json.load(open(saved[0] + ".tok.json", encoding="utf-8"))
    assert set(d) == {"merges", "itos"}
    assert d["itos"][0] == "<unk>"

def test_targets_are_inputs_shifted_by_one():
    x, y = make_windows(IDS, seq_len=4)
    assert (y.to_numpy()[:, :-1] == x.to_numpy()[:, 1:]).all()

def test_stride_skips_windows():
    x, _ = make_windows(IDS, seq_len=4, stride=2)
    assert x.to_numpy()[:, 0].tolist() == [3, 4, 5]       # starts 0, 2, 4

def test_too_few_tokens_raises():
    with pytest.raises(ValueError):
        make_windows(np.arange(4), seq_len=4)

