class Tokenizer:
    def __init__(self, merges, stoi, itos):
        self.merges = merges
        self.stoi = stoi
        self.itos = itos
        self.vocab_size = len(itos)

    def encode(self, text):
        ids = []
        for token in apply_merges(text, self.merges):
            ids.append(self.stoi.get(token, self.stoi[UNK]))
        return ids

    def decode(self, ids):
        tokens = []
        for i in ids:
            tokens.append(self.itos[i])
        return "".join(tokens)

