def count_words(text):
    counts = {}
    for word in PRE_TOKEN_RE.findall(text):
        counts[word] = counts.get(word, 0) + 1
    return counts

def merge_tokens(tokens, pair, merged):
    result = []
    i = 0
    while i < len(tokens):
        if i < len(tokens) - 1 and tokens[i] == pair[0] and tokens[i + 1] == pair[1]:
            result.append(merged)
            i += 2
        else:
            result.append(tokens[i])
            i += 1
    return result

def train_bpe(word_freqs, max_merges=1000):
    word_splits = {}
    for word in word_freqs:
        word_splits[word] = list(word)

    merges = []

    for step in range(max_merges):
        pair_freq = {}
        for word in word_splits:
            tokens = word_splits[word]
            weight = word_freqs[word]
            for i in range(len(tokens) - 1):
                key = (tokens[i], tokens[i + 1])
                pair_freq[key] = pair_freq.get(key, 0) + weight

        if len(pair_freq) == 0:
            break

        best_pair = None
        best_count = 0
        for pair in pair_freq:
            if pair_freq[pair] > best_count:
                best_count = pair_freq[pair]
                best_pair = pair

        if best_pair is None:
            break

        a, b = best_pair
        merged = a + b

        for word in word_splits:
            word_splits[word] = merge_tokens(word_splits[word], best_pair, merged)

        merges.append({"pair": best_pair, "merged": merged, "frequency": best_count})

    return merges

def apply_merges(text, merges):
    result = []

    for pre_token in PRE_TOKEN_RE.findall(text):
        tokens = list(pre_token)

        for m in merges:
            tokens = merge_tokens(tokens, m["pair"], m["merged"])
        result.extend(tokens)

    return result

def build_tokenizer(text, max_merges=1000):
    merges = train_bpe_on_text(text, max_merges)

    itos = [UNK]
    seen = {UNK}

    for ch in text:
        if ch not in seen:
            seen.add(ch)
            itos.append(ch)

    for m in merges:
        if m["merged"] not in seen:
            seen.add(m["merged"])
            itos.append(m["merged"])

    stoi = {}
    for i in range(len(itos)):
        stoi[itos[i]] = i

    return Tokenizer(merges, stoi, itos)

def batch_loss_and_grads(params, xb, yb, cfg: ModelConfig):
    B = len(xb)
    grads = {k: np.zeros_like(v) for k, v in params.items()}
    total_loss = 0.0

    for x, y in zip(xb, yb):
        loss, g = loss_and_grads(params, x, y, cfg)
        total_loss += loss / B

        for k in grads:
            grads[k] += g[k] / B

    return total_loss, grads

def validation_loss(params, cfg, inputs, targets):
    losses = []

    for x, y in zip(inputs.to_numpy(), targets.to_numpy()):
        logits, _ = forward(params, x, cfg)
        loss, _ = cross_entropy_forward(logits, y)
        losses.append(loss)

    return float(np.mean(losses))

def embed_backward(dX0, ids, grads):
    np.add.at(grads["tok_emb"], ids, dX0) # grads["tok_emb"][ids[t]] += dX0[t]
    grads["pos_emb"][: len(ids)] += dX0

def split_heads(M, H):
    T, d = M.shape
    return M.reshape(T, H, d // H).transpose(1, 0, 2)

def merge_heads(Mh):
    H, T, dh = Mh.shape
    return Mh.transpose(1, 0, 2).reshape(T, H * dh)

def ffn_forward(Xn, params, p):
    Z = Xn @ params[p + "ff1_w"] + params[p + "ff1_b"]
    A = relu_forward(Z)

    return A @ params[p + "ff2_w"] + params[p + "ff2_b"], dict(Xn=Xn, Z=Z, A=A)

def forward(params, ids, cfg: ModelConfig):
    assert len(ids) <= cfg.context_len, "sequence longer than the position table"

    X = embed_forward(params, ids)
    block_caches = []

    for l in range(cfg.num_layers):
        X, c = block_forward(X, params, l, cfg)
        block_caches.append(c)

    Xf, c_lnf = layer_norm_forward(X, params["lnf_g"], params["lnf_b"], cfg.ln_eps)
    logits = Xf @ params["head_w"] + params["head_b"]

    return logits, dict(blocks=block_caches, lnf=c_lnf, Xf=Xf)
